\big\langle u_{k}v_{k}\big\rangle+\rho\big\langle u_{k}\big\rangle  .
\end{equation*}
On the homogeneous manifold $w_{l}\equiv w$, $\mu_{l}\equiv\mu$ and
$c_{kl}=c$, $k\ne l$, $s_{kk}=1$,

\begin{equation*}
