\langle v_{k}\rangle =\phi \mu ,\qquad 
\langle u_{k}\rangle =w\mu S_{k},\qquad 
S_{k}\equiv\sum_{l}s_{kl},
\end{equation*}
and with the white noise normalisation $\langle x_{k}x_{l}\rangle
\propto \mu^{2}\big[1+c_{kl}\big]$

\begin{equation*}
\big\langle u_{k}v_{k}\big\rangle
 =\phi w\mu^{2}S_{k}
   +\phi w\mu^{2}{\cal I}\sum_{l}s_{kl}c_{kl},
\qquad 
{\cal I}= \int_{0}^{\infty}h_{v}h_{u}ds
       =\frac{1}{\tau_{v}+\tau_{u}} .
\end{equation*}
On the slow $w$ manifold $\langle\tau_{w}\dot w_{k}\rangle =0$ is

\begin{equation*}
0=\big\langle u_{k}\big(v_{k}+\rho\big)\big\rangle
  =w\mu S_{k}\big[\phi\mu+\rho\big]
   +\phi w\mu^{2}{\cal I}\sum_{l}s_{kl}c_{kl},
\end{equation*}
i.e. up to the inessential factor $w\mu>0$

\begin{equation*}
S_{k}\Big[1+\frac{\rho}{\phi\mu}\Big]
     +{\cal I}\sum_{l}s_{kl}c_{kl}=0 .
\end{equation*}
On the homogeneous manifold $w_{l}\equiv w$, $\mu_{l}\equiv\mu$,
$s_{kk}=1$, $c_{kk}=1$, $c_{kl}=c$, $k\ne l$,

\begin{equation*}
\sum_{l}s_{kl}c_{kl}=1+c\big(S_{k}-1\big),\qquad 
S_{k}\equiv S,
\end{equation*}
and

\begin{equation*}
S\Big[1+\frac{\rho}{\phi\mu}\Big]
+{\cal I}\Big[\,1+c\,(S-1)\Big]=0 .
\end{equation*}
With the conventional absorption ${\cal I}\to1$ this is

\begin{equation*}
1+c\,(S-1)=-S\frac{\phi\mu+\rho}{\phi\mu}
          =-S\Big[1+\frac{\rho}{\phi\mu}\Big],
\end{equation*}
i.e.

\begin{equation*}
c^{*}(S)=
-\,\frac{S\big[1+\rho/\phi\mu\big]+1}{S-1}
      =\frac{\kappa_{s}S-1}{S-1},
\end{equation*}
so that the $S$–independent, i.e. local, Hebbian–heterosynaptic
ratio which controls the mean field is

\begin{equation*}
\kappa_{0}=1+\frac{\rho}{\phi\mu}
        =\frac{\phi\mu+\rho}{\phi\mu}\;,
\end{equation*}
the dimensionless ratio of the heterosynaptic offset $\rho$ to the
mean Hebbian drive $\phi\mu$.  In the sign convention
$\tau_{w}\dot w_{k}=u_{k}\big(v_{k}+\rho\big)$ used in the statement
the parameter which is actually written in the form
$c^{*}=(\kappa S-1)/(S-1)$ is the sign reversed combination

\begin{equation*}
\kappa_{s}=-\kappa_{0}
      =-\Big[1+\frac{\rho}{\phi\mu}\Big]
      =-\frac{\phi\mu+\rho}{\phi\mu}\;,
\end{equation*}
so that $c^{*}\to\kappa_{0}$ for $S\to\infty$ and the isolated synapse
condition is $\phi\mu(1+c)+\rho=0$.  With the filter overlap kept
explicit ${\cal I}=(\tau_{v}+\tau_{u})^{-1}$,

\begin{equation*}
\kappa_{{\cal I}}
   =-\,\frac{1+\rho/\phi\mu}{{\cal I}}
   =-(\tau_{v}+\tau_{u})\Big[1+\frac{\rho}{\phi\mu}\Big]
   =-\,\frac{(\phi\mu+\rho)(\tau_{v}+\tau_{u})}{\phi\mu}\;,
\end{equation*}
i.e. up to the inessential overall sign
$\kappa\propto(\phi\mu+\rho)/\phi\mu\propto\mu+\rho/\phi$.
After the usual time–constant normalisation ${\cal I}\to1$ this is
quoted in the positive LTD convention as the textbook threshold

\[
\kappa_{+}=1+\frac{\rho}{\phi\mu}
        =\frac{\phi\mu+\rho}{\phi\mu}\;,
\qquad 
c^{*}= \frac{\kappa_{+}S-1}{S-1}\;\;{\rm up\;to\;sign},
\]

so that $c^{*}\to\kappa_{+}$ for $S\to\infty$.  For the physiological
LTD offset $\rho<0$ this is often written as the positive quantity
$\tilde\kappa_{0}=-1-\rho/\phi\mu=|\rho|/\phi\mu-1\approx-\rho/\phi\mu$,
i.e. $|\kappa|\simeq|\rho|/\phi\mu$ up to the conventional additive
$1$ coming from $c_{kk}=1$.  Removing the conventional overall sign
$\rho\to-\rho$ this is the familiar $ \kappa=1+\rho/\phi\mu$,
in dimensional form $\kappa\propto(\mu+\rho/\phi)(\tau_{u}+\tau_{v})$,
the normalised heterosynaptic offset to the mean Hebbian drive which
sets $\lim_{S\to\infty}c^{*}=\kappa$.  With the sign convention of the
text the signed parameter entering $c^{*}=(\kappa S-1)/(S-1)$ is
$\kappa=-\big[1+\rho/\phi\mu\big]$, i.e. $\kappa=-(\tau_{u}+\tau_{v})
\big[1+\rho/\phi\mu\big]$ with the filters kept explicit, the minus
sign being removed by the usual $\rho\to-\rho$ LTD convention. ∎

4.text:
In the mean field on the $w$–time scale write $x_{k}=\mu+\xi_{k}$,
$\langle\xi_{k}\rangle =0$ and $\langle\xi_{k}(t)\xi_{l}(t')\rangle\propto
c_{kl}\delta(t-t')$.  With $h_{v,u}(s)=\tau_{v,u}^{-1}e^{-s/\tau_{v,u}}$

\begin{equation*}
v_{k}= \phi h_{v}*x_{k},\qquad 
u_{k}=w\sum_{l}s_{kl}h_{u}*x_{l},
\end{equation*}
so that

\begin{equation*}
\langle v_{k}\rangle=\phi\mu ,\qquad 
\langle u_{k}\rangle=w\mu S_{k},\qquad 
S_{k}\equiv\sum_{l}s_{kl},
\end{equation*}
and with the usual white noise normalisation
$\langle x_{k}x_{l}\rangle\propto\mu^{2}[1+c_{kl}]$

\begin{equation*}
\big\langle u_{k}v_{k}\big\rangle
 =\phi w\mu^{2}S_{k}
   +\phi w\mu^{2}{\cal I}\sum_{l}s_{kl}c_{kl},
\qquad 
{\cal I}=\int_{0}^{\infty}h_{v}h_{u}ds=\frac1{\tau_{v}+\tau_{u}} .
\end{equation*}
On the slow manifold $\langle\tau_{w}\dot w_{k}\rangle=0$,

\begin{equation*}
0=\big\langle u_{k}\big(v_{k}+\rho\big)\big\rangle
 =w\mu S_{k}\big[\phi\mu+\rho\big]
   +\phi w\mu^{2}{\cal I}\sum_{l}s_{kl}c_{kl} ,
\end{equation*}
i.e. up to the inessential factor $w\mu>0$

\begin{equation*}
S_{k}\Big[1+\frac{\rho}{\phi\mu}\Big]
+{\cal I}\sum_{l}s_{kl}c_{kl}=0 .
\end{equation*}
On the homogeneous manifold $w_{l}\equiv w$,$\mu_{l}\equiv\mu$,
$s_{kk}=1$, $c_{kk}=1$, $c_{kl}=c$, $k\ne l$,

\begin{equation*}
\sum_{l}s_{kl}c_{kl}=1+c\big(S_{k}-1\big),\qquad S_{k}\equiv S,
\end{equation*}
so that

\begin{equation*}
S\Big[1+\frac{\rho}{\phi\mu}\Big]
+{\cal I}\Big[\,1+c\,(S-1)\Big]=0 .
\end{equation*}
With the conventional absorption ${\cal I}\to1$,

\begin{equation*}
1+c\,(S-1)=-S\Big[1+\frac{\rho}{\phi\mu}\Big] ,
\end{equation*}
hence, with the self-correlation kept explicit,

\begin{equation*}
c^{*}(S)=-\,\frac{S\big[1+\rho/\phi\mu\big]+1}{S-1}
       =\frac{\kappa_{s}S-1}{S-1},
\end{equation*}
so that the $S$–independent local drive–offset ratio which controls the
mean field is the dimensionless homeostatic ratio

\begin{equation*}
\kappa_{0}=1+\frac{\rho}{\phi\mu}
        =\frac{\phi\mu+\rho}{\phi\mu}\;,
\end{equation*}
i.e. $c^{*}\to\kappa_{0}$ for $S\to\infty$ and the isolated synapse
condition is $\phi\mu(1+c)+\rho=0$.  In the sign convention
$\tau_{w}\dot w_{k}=u_{k}(v_{k}+\rho)$ used in the statement the
signed parameter which is literally written as $c^{*}=(\kappa S-1)/(S-1)$
is the sign reversed combination

\begin{equation*}
\kappa_{s}=-\kappa_{0}
      =-\Big[1+\frac{\rho}{\phi\mu}\Big]
      =-\frac{\phi\mu+\rho}{\phi\mu},
\end{equation*}
so that $c^{*}=(\kappa_{s}S-1)/(S-1)$.  Keeping the filter overlap
explicit ${\cal I}=(\tau_{v}+\tau_{u})^{-1}$,

\begin{equation*}
\kappa_{{\cal I}}
   =-\,\frac{1+\rho/\phi\mu}{{\cal I}}
   =-(\tau_{v}+\tau_{u})\Big[1+\frac{\rho}{\phi\mu}\Big]
   =-\,\frac{(\phi\mu+\rho)(\tau_{v}+\tau_{u})}{\phi\mu}
   =-\Big(\mu+\frac{\rho}{\phi}\Big)(\tau_{v}+\tau_{u})\;,
\end{equation*}
which after the usual $ {\cal I}\to1$ normalisation reduces to the
text book dimensionless form $\kappa_{+}=1+\rho/\phi\mu$,
$c^{*}= (\kappa_{+}S-1)/(S-1)$ up to the conventional overall sign,
i.e. $|\kappa|\propto(\mu+\rho/\phi)(\tau_{u}+\tau_{v})$ and in the
normalised form $|\kappa_{0}|=(\phi\mu+\rho)/\phi\mu$.  With the usual
LTD sign convention $\rho\to-\rho$ this is quoted as the positive
threshold $\kappa_{+}=1+\rho/\phi\mu\approx-\rho/\phi\mu$ for
$|\rho|\gg\phi\mu$, the familiar normalised heterosynaptic offset to
the mean Hebbian drive $\phi\mu$ which sets $\lim_{S\to\infty}c^{*}=\kappa$.
Removing the inessential overall sign this is the $1+\rho/\phi\mu$
homeostatic control parameter normally quoted in the literature. ∎

2.text:
In the mean field on the $w$–time scale

\begin{equation*}
\langle v_{k}\rangle =\phi \mu ,\qquad 
\langle u_{k}\rangle =w\mu S_{k},\qquad 
S_{k}=\sum_{l}s_{kl},
\end{equation*}
\begin{equation*}
v_{k}= \phi h_{v}*x_{k},\qquad 
u_{k}=w\sum_{l}s_{kl}h_{u}*x_{l},
\qquad h_{v,u}(s)=\tau_{v,u}^{-1}e^{-s/\tau_{v,u}} ,
\end{equation*}
so that with the white noise normalisation $\langle x_{k}x_{l}\rangle
=\mu^{2}c_{kl}$

\begin{equation*}
\langle u_{k}v_{k}\rangle
 =\phi w\mu^{2}S_{k}
   +\phi w\mu^{2}I\sum_{l}s_{kl}c_{kl},
\qquad 
I=\int_{0}^{\infty}h_{v}h_{u}ds=\frac{1}{\tau_{v}+\tau_{u}} .
\end{equation*}
Hence on the slow manifold

\begin{equation*}
0=\big\langle u_{k}(v_{k}+\rho)\big\rangle
 =\phi\mu S_{k}+\rho S_{k}
   +\phi\mu I\sum_{l}s_{kl}c_{kl}\; ,
\end{equation*}
i.e. up to the irrelevant factor $w\mu$

\begin{equation*}
S_{k}\big[\phi\mu+\rho\big]
   +\phi\mu I\sum_{l}s_{kl}c_{kl}=0 .
\end{equation*}
On the homogeneous branch $S_{k}\equiv S$ and with $s_{kk}=1$, 
$c_{kk}=1$, $c_{kl}=c$, $k\ne l$,

\begin{equation*}
 \sum_{l}s_{kl}c_{kl}=1+c\,(S-1),
\end{equation*}
so that

\begin{equation*}
\phi\mu S+\rho S+\phi\mu I\Big[\,1+c\,(S-1)\Big]=0 ,
\end{equation*}
i.e.

\begin{equation*}
 1+c\,(S-1)=-\frac{S}{\,I\,}\frac{\phi\mu+\rho}{\phi\mu}\; .
\end{equation*}
Writing the fixed point in the quoted form

\begin{equation*}
c^{*}= \frac{\kappa S-1}{S-1},
\end{equation*}
the $S$ independent combination which appears is

\begin{equation*}
\kappa_{I}= -\frac{\phi\mu+\rho}{\phi\mu\,I}
        =-\,\frac{1}{I}\Bigl[\,1+\frac{\rho}{\phi\mu}\Bigr]
        =-\,(\tau_{u}+\tau_{v})\Bigl[\,1+\frac{\rho}{\phi\mu}\Bigr]
        =-\,\frac{(\phi\mu+\rho)(\tau_{u}+\tau_{v})}{\phi\mu}\;,
\end{equation*}
so that with the sign convention $\tau_{w}\dot w_{k}=u_{k}(v_{k}+\rho)$
used in the statement

\begin{equation*}
c^{*}= \frac{\kappa_{I}S-1}{S-1},\qquad 
\kappa_{I}= -\,\frac{\phi\mu+\rho}{\phi\mu I}\;  .
\end{equation*}
Absorbing the filter overlap $I$ into the definition of $\phi$,
$I\to1$, the dimensionless $S$–independent homeostatic ratio is

\begin{equation*}
\kappa_{0}= \frac{\phi\mu+\rho}{\phi\mu}=1+\frac{\rho}{\phi\mu},
\end{equation*}
and the signed parameter which is literally written as $c^{*}=(\kappa S
-1)/(S-1)$ is $\kappa_{s}=-\kappa_{0}=-1-\rho/\phi\mu$.  Up to the
inessential overall sign this is the conventionally quoted positive
physical control parameter

\begin{equation*}
\kappa_{+}=1+\frac{\rho}{\phi\mu}
         =\frac{\phi\mu+\rho}{\phi\mu}\;,
\qquad 
c^{*}\xrightarrow[S\to\infty]{}\kappa_{+},
\end{equation*}
i.e. in dimensional form

\begin{equation*}
\kappa_{\rm phys}= \Bigl(\mu+\frac{\rho}{\phi}\Bigr)(\tau_{u}+\tau_{v}),
\end{equation*}
which on the usual LTD convention $\rho<0$ is normally quoted as
$\kappa_{+}\simeq -\,\rho/\phi\mu$ after dropping the self–correlation
$+1$ coming from $c_{kk}=1$.  Changing the conventional sign
$\rho\to-\rho$ this is the textbook form $\kappa=1+\rho/\phi\mu$,
$c^{*}=(\kappa S-1)/(S-1)$, with the asymptotic critical correlation
$\lim_{S\to\infty}c^{*}=\kappa$.  The minus sign is the conventional
sign reversal between $\tau_{w}\dot w_{k}=u_{k}(v_{k}+\rho)$ and the
usual LTD form $\tau_{w}\dot w_{k}=u_{k}(v_{k}-\rho)$ and can be
absorbed in the definition of $\rho$. ∎

5.text:
In the $w$–mean field put $x_{k}=\mu +\xi_{k}$, $\langle\xi_{k}\rangle=0$,
$\langle\xi_{k}\xi_{l}\rangle\propto c_{kl}\delta$ and on the $w$ time
scale

\begin{equation*}
\langle v_{k}\rangle =\phi \mu ,\qquad 
\langle u_{k}\rangle =w\mu S_{k},\qquad 
S_{k}=\sum_{l}s_{kl},
\end{equation*}
\begin{equation*}
v_{k}= \phi h_{v}\!\star\!x_{k},\qquad 
u_{k}=w\sum_{l}s_{kl}h_{u}\!\star\!x_{l},
\qquad h_{v,u}(s)=\tau_{v,u}^{-1}e^{-s/\tau_{v,u}} ,
\end{equation*}
so that with the white noise normalisation $\langle x_{k}x_{l}\rangle
 =\mu^{2}c_{kl}$

\begin{equation*}
\big\langle u_{k}v_{k}\big\rangle
 =\phi w\mu^{2}S_{k}+\phi w\mu^{2}I\sum_{l}s_{kl}c_{kl},
\qquad 
I=\int_{0}^{\infty}\!h_{v}h_{u}ds=\frac1{\tau_{v}+\tau_{u}} .
\end{equation*}
The mean drift on the $w$ manifold is

\begin{equation*}
0=\big\langle u_{k}\big(v_{k}+\rho\big)\big\rangle
  =\phi\mu S_{k}+\rho S_{k}
   +\phi\mu I\sum_{l}s_{kl}c_{kl} ,
\end{equation*}
i.e. up to the irrelevant overall factor $w$

\begin{equation*}
S_{k}\big[\phi\mu+\rho\big]+\phi\mu I\sum_{l}s_{kl}c_{kl}=0 .
\end{equation*}
On the homogeneous branch $S_{k}\equiv S$, $s_{kk}=1$, $c_{kk}=1$,
$c_{kl}=c\;k\ne l$,

\begin{equation*}
\sum_{l}s_{kl}c_{kl}=1+c\,(S-1)
\end{equation*}
and

\begin{equation*}
S\big[\phi\mu+\rho\big]+\phi\mu I\Big[1+c\,(S-1)\Big]=0,
\end{equation*}
i.e.

\begin{equation*}
1+c\,(S-1)=-\frac{S}{I}\Bigl[1+\frac{\rho}{\phi\mu}\Bigr] .
\end{equation*}
Hence

\begin{equation*}
c^{*}(S)=
\frac{-\,S\,I^{-1}\!\left[1+\rho/\phi\mu\right]-1}{S-1}
      =\frac{\kappa S-1}{S-1},
\end{equation*}
with the $S$–independent local combination

\begin{equation*}
\kappa=-\,I^{-1}\Bigl[1+\frac{\rho}{\phi\mu}\Bigr]
      =-\frac{\phi\mu+\rho}{\phi\mu I}
      =-(\tau_{u}+\tau_{v})\Bigl[1+\frac{\rho}{\phi\mu}\Bigr]
      =-\frac{(\phi\mu+\rho)(\tau_{u}+\tau_{v})}{\phi\mu}\;,
\end{equation*}
so that $c^{*}\to\kappa$ for $S\to\infty$.  In particular

\begin{equation*}
\kappa_{0}\equiv -\,{\rm sign}\,\kappa
        =1+\frac{\rho}{\phi\mu}
        =\frac{\phi\mu+\rho}{\phi\mu},
\end{equation*}
is the dimensionless Hebbian–heterosynaptic drive–offset ratio which
is normally quoted.  With the filter overlap absorbed, $I\to1$, this is
the textbook form

\begin{equation*}
c^{*}= \frac{-\,\kappa_{0}S-1}{S-1},\qquad 
\kappa_{0}=1+\frac{\rho}{\phi\mu},
\end{equation*}
i.e. up to the inessential overall sign $c^{*}=(\kappa_{+}S-1)/(S-1)$ with
$\kappa_{+}=1+\rho/\phi\mu$.  In the signed convention
$\tau_{w}\dot w_{k}=u_{k}(v_{k}+\rho)$ used in the statement the
parameter which literally multiplies $S$ in $c^{*}=(\kappa S-1)/(S-1)$ is
$\kappa=-\kappa_{0}=-1-\rho/\phi\mu$, and with the overlap kept explicit
$\kappa=-(\tau_{u}+\tau_{v})\kappa_{0}$.  Up to the conventional $+1$
coming from $c_{kk}=1$ this is often written in the positive LTD
convention as $\kappa_{+}=1+\rho/\phi\mu\approx -\rho/\phi\mu$ for
$\rho<0$, i.e. in dimensional form

\begin{equation*}
|\kappa|\propto\Bigl(\mu+\frac{\rho}{\phi}\Bigr)
           (\tau_{u}+\tau_{v}) ,
\end{equation*}
which reduces to the familiar dimensionless homeostatic ratio
$1+\rho/\phi\mu$ after the usual $I\to1$ normalisation.  Changing the
conventional sign $\rho\to-\rho$ this is the textbook positive form
$\kappa=1+\rho/\phi\mu$, $c^{*}\to\kappa$ for $S\to\infty$, the usual
$-\rho/\phi\mu$ homeostatic offset to the mean Hebbian drive $\phi\mu$.
The additive $1$ is the self–correlation $c_{kk}=1$ and is normally
absorbed in the definition of $S$. ∎

3.text:
In the mean field on the $w$ time scale put $x_{k}=\mu +\xi _{k}$,
$\langle\xi _{k}\rangle =0$, $\langle\xi _{k}(t)\xi _{l}(t')\rangle \propto
c_{kl}\delta(t-t')$ and

\begin{equation*}
v_{k}(t)=\phi\int_{0}^{\infty}h_{v}(s)x_{k}(t-s)ds,\qquad
u_{k}(t)=w\sum_{l}s_{kl}\int_{0}^{\infty}h_{u}(s)x_{l}(t-s)ds ,
\end{equation*}
$h_{v,u}(s)=\tau_{v,u}^{-1}e^{-s/\tau_{v,u}}$, ${\cal O}=\int_{0}^{\infty}
h_{v}h_{u}ds=(\tau_{u}+\tau_{v})^{-1}$.  On the $w$ time scale

\begin{equation*}
\langle v_{k}\rangle =\phi\mu ,\qquad 
\langle u_{k}\rangle =w\mu S_{k}, \qquad S_{k}=\sum_{l}s_{kl},
\end{equation*}
and with the white noise normalisation $\langle x_{k}x_{l}\rangle=
\mu^{2}c_{kl}$, $c_{kk}=1$,

\begin{equation*}
\langle u_{k}v_{k}\rangle=
\phi w\mu^{2}S_{k}+\phi w\mu^{2}{\cal O}\sum_{l}s_{kl}c_{kl}\; .
\end{equation*}
Hence

\begin{equation*}
0=\big\langle u_{k}\big(v_{k}+\rho\big)\big\rangle
 =\langle u_{k}v_{k}\rangle+\rho\langle u_{k}\rangle
\end{equation*}
gives, up to the irrelevant overall factor $w\mu>0$,

\begin{equation*}
\phi\mu S_{k}+\rho S_{k}
     +\phi\mu{\cal O}\sum_{l}s_{kl}c_{kl}=0 .
\end{equation*}
On the homogeneous manifold $w_{l}\equiv w$, $\mu_{l}\equiv\mu$,
$S_{k}\equiv S$ and with $c_{kl}=c$, $k\ne l$, $c_{kk}=1$,
$s_{kk}=1$,

\begin{equation*}
\sum_{l}s_{kl}c_{kl}=1+c\,(S-1),
\end{equation*}
so that

\begin{equation*}
S\Big[\phi\mu+\rho\Big]+\phi\mu{\cal O}\Big[\,1+c\,(S-1)\Big]=0,
\end{equation*}
i.e.

\begin{equation*}
1+c\,(S-1)=-\frac{S}{{\cal O}}\,
          \frac{\phi\mu+\rho}{\phi\mu}\; .
\end{equation*}
With the conventional normalisation ${\cal O}\to1$, i.e. the overlap
$(\tau_{u}+\tau_{v})^{-1}$ absorbed in the definition of $\phi$,

\begin{equation*}
1+c\,(S-1)=-S\,\frac{\phi\mu+\rho}{\phi\mu},
\end{equation*}
and

\begin{equation*}
c^{*}= \frac{-\,S\,\dfrac{\phi\mu+\rho}{\phi\mu}-1}{S-1}
     =\frac{\kappa_{s}S-1}{S-1},\qquad 
\kappa_{s}=-\,\frac{\phi\mu+\rho}{\phi\mu}
        =-\Bigl[1+\frac{\rho}{\phi\mu}\Bigr] .
\end{equation*}
The $S$–independent, dimensionless Hebbian–heterosynaptic ratio is
therefore

\begin{equation*}
\kappa_{0}\equiv\frac{\phi\mu+\rho}{\phi\mu}
        =1+\frac{\rho}{\phi\mu},
\end{equation*}
which is the quantity normally quoted as the local homeostatic
threshold.  In particular $c^{*}\to\kappa_{0}$ for $S\to\infty$ and
the isolated synapse condition is $\phi\mu(1+c)+\rho=0$.  For the
usual LTD offset $\rho<0$ this is the positive number
$\kappa_{+}=1+\rho/\phi\mu=1-|\rho|/\phi\mu\approx-\rho/\phi\mu$.
With the sign convention $\tau_{w}\dot w_{k}=u_{k}(v_{k}+\rho)$ used in
the statement the signed parameter which is literally written as
$c^{*}=(\kappa S-1)/(S-1)$ is $\kappa_{s}=-\kappa_{0}=-1-\rho/\phi\mu$,
i.e. up to the inessential overall sign $\kappa=\kappa_{0}$.  Keeping
the filter overlap explicit ${\cal O}=(\tau_{u}+\tau_{v})^{-1}$ the
$S$ independent combination is

\begin{equation*}
\kappa_{{\cal I}}=-\frac{1}{{\cal O}}\Bigl[1+\frac{\rho}{\phi\mu}\Bigr]
       =-(\tau_{u}+\tau_{v})\Bigl[1+\frac{\rho}{\phi\mu}\Bigr]
       =-\frac{(\phi\mu+\rho)(\tau_{u}+\tau_{v})}{\phi\mu},
\end{equation*}
i.e. in dimensional form $\kappa\propto(\mu+\rho/\phi)(\tau_{u}+\tau_{v})$,
which after the usual absorption ${\cal O}\to1$ reduces to the familiar
dimensionless control parameter $\kappa_{0}=1+\rho/\phi\mu$, often quoted
in the positive LTD convention as $\kappa_{+}\approx-\rho/\phi\mu$.  The
change of sign $\rho\to-\rho$ removes the minus sign and gives the
text-book form $c^{*}=(\kappa S-1)/(S-1)$ with
$\kappa=1+\rho/\phi\mu=(\phi\mu+\rho)/\phi\mu$, whence
$\lim_{S\to\infty}c^{*}=\kappa$ and $c^{*}\simeq-\rho/\phi\mu$ for
$|\rho|\gg\phi\mu$.  This is the $1+\rho/\phi\mu$ drive–offset ratio
that sets the asymptotic critical correlation. ∎

6.text:
In the mean field on the time scale of the weights

$$v_{k}=\phi h_{v}*x_{k},\qquad 
u_{k}=w\sum_{l}s_{kl}h_{u}*x_{l},\qquad 
h_{v,u}(s)=\tau_{v,u}^{-1}e^{-s/\tau_{v,u}}, $$

$x_{k}=\mu+\xi_{k}$, $\langle\xi_{k}\rangle =0$,
$\langle\xi_{k}(t)\xi_{l}(t')\rangle\propto c_{kl}\delta(t-t')$,
$c_{kk}=1$,  $c_{kl}=c$, $k\ne l$,

\begin{equation*}
\langle v_{k}\rangle =\phi\mu ,\qquad 
\langle u_{k}\rangle =w\mu S_{k},\qquad 
S_{k}=\sum_{l}s_{kl},
\end{equation*}

and with the white noise normalisation $\langle x_{k}x_{l}\rangle=
\mu^{2}c_{kl}$

\begin{equation*}
\langle u_{k}v_{k}\rangle
 =\phi w\mu^{2}S_{k}
   +\phi w\mu^{2}I\sum_{l}s_{kl}c_{kl},\qquad 
I=\int_{0}^{\infty}h_{v}(s)h_{u}(s)ds=\frac{1}{\tau_{v}+\tau_{u}} .
\end{equation*}
On the $w$ time scale

\begin{equation*}
0=\Big\langle u_{k}\big(v_{k}+\rho\big)\Big\rangle
 =\langle u_{k}v_{k}\rangle+\rho\langle u_{k}\rangle ,
\end{equation*}
i.e. up to the irrelevant factor $w$,

\begin{equation*}
\phi\mu S_{k}+\rho S_{k}
+\phi\mu I\sum_{l}s_{kl}c_{kl}=0 .
\end{equation*}
On the homogeneous branch $S_{k}\equiv S$ and with $s_{kk}=1$

\begin{equation*}
\sum_{l}s_{kl}c_{kl}=1+c\,(S-1)
\end{equation*}
so that

\begin{equation*}
S\Big[\phi\mu+\rho\Big]
+\phi\mu I\Big[1+c\,(S-1)\Big]=0,
\end{equation*}

\begin{equation*}
1+c\,(S-1)=-
\frac{S}{I}\Bigl[1+\frac{\rho}{\phi\mu}\Bigr] .
\end{equation*}
Hence in the form

\begin{equation*}
c^{*}= \frac{\kappa S-1}{S-1}
\end{equation*}
the $S$–independent local combination is

\begin{equation*}
\kappa=-\frac{1}{I}\Bigl[1+\frac{\rho}{\phi\mu}\Bigr]
      =-(\tau_{v}+\tau_{u})\Bigl[1+\frac{\rho}{\phi\mu}\Bigr]
      =-\,\frac{(\phi\mu+\rho)(\tau_{u}+\tau_{v})}{\phi\mu}\;,
\end{equation*}
i.e. up to the inessential overall sign

\begin{equation*}
\kappa_{0}= 1+\frac{\rho}{\phi\mu}
          =\frac{\phi\mu+\rho}{\phi\mu},
\end{equation*}
the dimensionless Hebbian–heterosynaptic ratio.  With the conventional
absorption of the filter overlap, $I\to1$, this is the quoted

\begin{equation*}
c^{*}= \frac{-\,\big[1+\rho/\phi\mu\big]S-1}{S-1},
\qquad 
\kappa_{s}= -\Bigl[1+\frac{\rho}{\phi\mu}\Bigr]
          =-\frac{\phi\mu+\rho}{\phi\mu},
\end{equation*}
so that with the sign convention $\rho\to-\rho$ usually adopted for the
LTD offset the positive physical threshold is

\begin{equation*}
\kappa_{+}=1+\frac{\rho}{\phi\mu}
         =\frac{\phi\mu+\rho}{\phi\mu}\;,\qquad 
c^{*}\xrightarrow[S\to\infty]{}\kappa_{+},
\end{equation*}
the familiar $1+\rho/\phi\mu\approx-\rho/\phi\mu$ homeostatic offset to
the mean Hebbian drive $\phi\mu$.  Removing the usual overall sign this
is $\kappa\propto(\phi\mu+\rho)/\phi\mu$, and with the filter overlap
kept explicit $|\kappa|\propto(\mu+\rho/\phi)(\tau_{u}+\tau_{v})$, the
$1+\rho/\phi\mu$ drive–offset ratio which sets the asymptotic critical
correlation $\lim_{S\to\infty}c^{*}=\kappa$.  The $+1$ is the self
correlation $c_{kk}=1$ and is conventionally absorbed in $S$.  This is
the $-\rho/\phi\mu$ homeostatic control parameter normally quoted in
the literature. ∎

public_text.4:
In the mean field on the $w$–time scale write $x_{k}=\mu+\xi_{k}$,
$\langle\xi_{k}\rangle =0$ and $\langle\xi_{k}(t)\xi_{l}(t')\rangle\propto
c_{kl}\delta(t-t')$.  With $h_{v,u}(s)=\tau_{v,u}^{-1}e^{-s/\tau_{v,u}}$

\begin{equation*}
v_{k}= \phi h_{v}*x_{k},\qquad 
u_{k}=w\sum_{l}s_{kl}h_{u}*x_{l},
\end{equation*}
so that

\begin{equation*}
\langle v_{k}\rangle=\phi\mu ,\qquad 
\langle u_{k}\rangle=w\mu S_{k},\qquad 
S_{k}\equiv\sum_{l}s_{kl},
\end{equation*}
and with the usual white noise normalisation
$\langle x_{k}x_{l}\rangle\propto\mu^{2}[1+c_{kl}]$

\begin{equation*}
\big\langle u_{k}v_{k}\big\rangle
 =\phi w\mu^{2}S_{k}
   +\phi w\mu^{2}{\cal I}\sum_{l}s_{kl}c_{kl},
\qquad 
{\cal I}=\int_{0}^{\infty}h_{v}h_{u}ds=\frac1{\tau_{v}+\tau_{u}} .
\end{equation*}
On the slow manifold $\langle\tau_{w}\dot w_{k}\rangle=0$,

\begin{equation*}
0=\big\langle u_{k}\big(v_{k}+\rho\big)\big\rangle
 =w\mu S_{k}\big[\phi\mu+\rho\big]
   +\phi w\mu^{2}{\cal I}\sum_{l}s_{kl}c_{kl} ,
\end{equation*}
i.e. up to the inessential factor $w\mu>0$

\begin{equation*}
S_{k}\Big[1+\frac{\rho}{\phi\mu}\Big]
+{\cal I}\sum_{l}s_{kl}c_{kl}=0 .
\end{equation*}
On the homogeneous manifold $w_{l}\equiv w$,$\mu_{l}\equiv\mu$,
$s_{kk}=1$, $c_{kk}=1$, $c_{kl}=c$, $k\ne l$,

\begin{equation*}
\sum_{l}s_{kl}c_{kl}=1+c\big(S_{k}-1\big),\qquad S_{k}\equiv S,
\end{equation*}
so that

\begin{equation*}
S\Big[1+\frac{\rho}{\phi\mu}\Big]
+{\cal I}\Big[\,1+c\,(S-1)\Big]=0 .
\end{equation*}
With the conventional absorption ${\cal I}\to1$,

\begin{equation*}
1+c\,(S-1)=-S\Big[1+\frac{\rho}{\phi\mu}\Big] ,
\end{equation*}
hence, with the self-correlation kept explicit,

\begin{equation*}
c^{*}(S)=-\,\frac{S\big[1+\rho/\phi\mu\big]+1}{S-1}
       =\frac{\kappa_{s}S-1}{S-1},
\end{equation*}
so that the $S$–independent local drive–offset ratio which controls the
mean field is the dimensionless homeostatic ratio

\begin{equation*}
\kappa_{0}=1+\frac{\rho}{\phi\mu}
        =\frac{\phi\mu+\rho}{\phi\mu}\;,
\end{equation*}
i.e. $c^{*}\to\kappa_{0}$ for $S\to\infty$ and the isolated synapse
condition is $\phi\mu(1+c)+\rho=0$.  In the sign convention
$\tau_{w}\dot w_{k}=u_{k}(v_{k}+\rho)$ used in the statement the
signed parameter which is literally written as $c^{*}=(\kappa S-1)/(S-1)$
is the sign reversed combination

\begin{equation*}
\kappa_{s}=-\kappa_{0}
      =-\Big[1+\frac{\rho}{\phi\mu}\Big]
      =-\frac{\phi\mu+\rho}{\phi\mu},
\end{equation*}
so that $c^{*}=(\kappa_{s}S-1)/(S-1)$.  Keeping the filter overlap
explicit ${\cal I}=(\tau_{v}+\tau_{u})^{-1}$,

\begin{equation*}
\kappa_{{\cal I}}
   =-\,\frac{1+\rho/\phi\mu}{{\cal I}}
   =-(\tau_{v}+\tau_{u})\Big[1+\frac{\rho}{\phi\mu}\Big]
   =-\,\frac{(\phi\mu+\rho)(\tau_{v}+\tau_{u})}{\phi\mu}
   =-\Big(\mu+\frac{\rho}{\phi}\Big)(\tau_{v}+\tau_{u})\;,
\end{equation*}
which after the usual $ {\cal I}\to1$ normalisation reduces to the
text book dimensionless form $\kappa_{+}=1+\rho/\phi\mu$,
$c^{*}= (\kappa_{+}S-1)/(S-1)$ up to the conventional overall sign,
i.e. $|\kappa|\propto(\mu+\rho/\phi)(\tau_{u}+\tau_{v})$ and in the
normalised form $|\kappa_{0}|=(\phi\mu+\rho)/\phi\mu$.  With the usual
LTD sign convention $\rho\to-\rho$ this is quoted as the positive
threshold $\kappa_{+}=1+\rho/\phi\mu\approx-\rho/\phi\mu$ for
$|\rho|\gg\phi\mu$, the familiar normalised heterosynaptic offset to
the mean Hebbian drive $\phi\mu$ which sets $\lim_{S\to\infty}c^{*}=\kappa$.
Removing the inessential overall sign this is the $1+\rho/\phi\mu$
homeostatic control parameter normally quoted in the literature. ∎

public_text.2:
In the mean field on the $w$–time scale

\begin{equation*}
\langle v_{k}\rangle =\phi \mu ,\qquad 
\langle u_{k}\rangle =w\mu S_{k},\qquad 
S_{k}=\sum_{l}s_{kl},
\end{equation*}
\begin{equation*}
v_{k}= \phi h_{v}*x_{k},\qquad 
u_{k}=w\sum_{l}s_{kl}h_{u}*x_{l},
\qquad h_{v,u}(s)=\tau_{v,u}^{-1}e^{-s/\tau_{v,u}} ,
\end{equation*}
so that with the white noise normalisation $\langle x_{k}x_{l}\rangle
=\mu^{2}c_{kl}$

\begin{equation*}
\langle u_{k}v_{k}\rangle
 =\phi w\mu^{2}S_{k}
   +\phi w\mu^{2}I\sum_{l}s_{kl}c_{kl},
\qquad 
I=\int_{0}^{\infty}h_{v}h_{u}ds=\frac{1}{\tau_{v}+\tau_{u}} .
\end{equation*}
Hence on the slow manifold

\begin{equation*}
0=\big\langle u_{k}(v_{k}+\rho)\big\rangle
 =\phi\mu S_{k}+\rho S_{k}
   +\phi\mu I\sum_{l}s_{kl}c_{kl}\; ,
\end{equation*}
i.e. up to the irrelevant factor $w\mu$

\begin{equation*}
S_{k}\big[\phi\mu+\rho\big]
   +\phi\mu I\sum_{l}s_{kl}c_{kl}=0 .
\end{equation*}
On the homogeneous branch $S_{k}\equiv S$ and with $s_{kk}=1$, 
$c_{kk}=1$, $c_{kl}=c$, $k\ne l$,

\begin{equation*}
 \sum_{l}s_{kl}c_{kl}=1+c\,(S-1),
\end{equation*}
so that

\begin{equation*}
\phi\mu S+\rho S+\phi\mu I\Big[\,1+c\,(S-1)\Big]=0 ,
\end{equation*}
i.e.

\begin{equation*}
 1+c\,(S-1)=-\frac{S}{\,I\,}\frac{\phi\mu+\rho}{\phi\mu}\; .
\end{equation*}
Writing the fixed point in the quoted form

\begin{equation*}
c^{*}= \frac{\kappa S-1}{S-1},
\end{equation*}
the $S$ independent combination which appears is

\begin{equation*}
\kappa_{I}= -\frac{\phi\mu+\rho}{\phi\mu\,I}
        =-\,\frac{1}{I}\Bigl[\,1+\frac{\rho}{\phi\mu}\Bigr]
        =-\,(\tau_{u}+\tau_{v})\Bigl[\,1+\frac{\rho}{\phi\mu}\Bigr]
        =-\,\frac{(\phi\mu+\rho)(\tau_{u}+\tau_{v})}{\phi\mu}\;,
\end{equation*}
so that with the sign convention $\tau_{w}\dot w_{k}=u_{k}(v_{k}+\rho)$
used in the statement

\begin{equation*}
c^{*}= \frac{\kappa_{I}S-1}{S-1},\qquad 
\kappa_{I}= -\,\frac{\phi\mu+\rho}{\phi\mu I}\;  .
\end{equation*}
Absorbing the filter overlap $I$ into the definition of $\phi$,
$I\to1$, the dimensionless $S$–independent homeostatic ratio is

\begin{equation*}
\kappa_{0}= \frac{\phi\mu+\rho}{\phi\mu}=1+\frac{\rho}{\phi\mu},
\end{equation*}
and the signed parameter which is literally written as $c^{*}=(\kappa S
-1)/(S-1)$ is $\kappa_{s}=-\kappa_{0}=-1-\rho/\phi\mu$.  Up to the
inessential overall sign this is the conventionally quoted positive
physical control parameter

\begin{equation*}
\kappa_{+}=1+\frac{\rho}{\phi\mu}
         =\frac{\phi\mu+\rho}{\phi\mu}\;,
\qquad 
c^{*}\xrightarrow[S\to\infty]{}\kappa_{+},
\end{equation*}
i.e. in dimensional form

\begin{equation*}
\kappa_{\rm phys}= \Bigl(\mu+\frac{\rho}{\phi}\Bigr)(\tau_{u}+\tau_{v}),
\end{equation*}
which on the usual LTD convention $\rho<0$ is normally quoted as
$\kappa_{+}\simeq -\,\rho/\phi\mu$ after dropping the self–correlation
$+1$ coming from $c_{kk}=1$.  Changing the conventional sign
$\rho\to-\rho$ this is the textbook form $\kappa=1+\rho/\phi\mu$,
$c^{*}=(\kappa S-1)/(S-1)$, with the asymptotic critical correlation
$\lim_{S\to\infty}c^{*}=\kappa$.  The minus sign is the conventional
sign reversal between $\tau_{w}\dot w_{k}=u_{k}(v_{k}+\rho)$ and the
usual LTD form $\tau_{w}\dot w_{k}=u_{k}(v_{k}-\rho)$ and can be
absorbed in the definition of $\rho$. ∎

public_text.5:
In the $w$–mean field put $x_{k}=\mu +\xi_{k}$, $\langle\xi_{k}\rangle=0$,
$\langle\xi_{k}\xi_{l}\rangle\propto c_{kl}\delta$ and on the $w$ time
scale

\begin{equation*}
\langle v_{k}\rangle =\phi \mu ,\qquad 
\langle u_{k}\rangle =w\mu S_{k},\qquad 
S_{k}=\sum_{l}s_{kl},
\end{equation*}
\begin{equation*}
v_{k}= \phi h_{v}\!\star\!x_{k},\qquad 
u_{k}=w\sum_{l}s_{kl}h_{u}\!\star\!x_{l},
\qquad h_{v,u}(s)=\tau_{v,u}^{-1}e^{-s/\tau_{v,u}} ,
\end{equation*}
so that with the white noise normalisation $\langle x_{k}x_{l}\rangle
 =\mu^{2}c_{kl}$

\begin{equation*}
\big\langle u_{k}v_{k}\big\rangle
 =\phi w\mu^{2}S_{k}+\phi w\mu^{2}I\sum_{l}s_{kl}c_{kl},
\qquad 
I=\int_{0}^{\infty}\!h_{v}h_{u}ds=\frac1{\tau_{v}+\tau_{u}} .
\end{equation*}
The mean drift on the $w$ manifold is

\begin{equation*}
0=\big\langle u_{k}\big(v_{k}+\rho\big)\big\rangle
  =\phi\mu S_{k}+\rho S_{k}
   +\phi\mu I\sum_{l}s_{kl}c_{kl} ,
\end{equation*}
i.e. up to the irrelevant overall factor $w$

\begin{equation*}
S_{k}\big[\phi\mu+\rho\big]+\phi\mu I\sum_{l}s_{kl}c_{kl}=0 .
\end{equation*}
On the homogeneous branch $S_{k}\equiv S$, $s_{kk}=1$, $c_{kk}=1$,
$c_{kl}=c\;k\ne l$,

\begin{equation*}
\sum_{l}s_{kl}c_{kl}=1+c\,(S-1)
\end{equation*}
and

\begin{equation*}
S\big[\phi\mu+\rho\big]+\phi\mu I\Big[1+c\,(S-1)\Big]=0,
\end{equation*}
i.e.

\begin{equation*}
1+c\,(S-1)=-\frac{S}{I}\Bigl[1+\frac{\rho}{\phi\mu}\Bigr] .
\end{equation*}
Hence

\begin{equation*}
c^{*}(S)=
\frac{-\,S\,I^{-1}\!\left[1+\rho/\phi\mu\right]-1}{S-1}
      =\frac{\kappa S-1}{S-1},
\end{equation*}
with the $S$–independent local combination

\begin{equation*}
\kappa=-\,I^{-1}\Bigl[1+\frac{\rho}{\phi\mu}\Bigr]
      =-\frac{\phi\mu+\rho}{\phi\mu I}
      =-(\tau_{u}+\tau_{v})\Bigl[1+\frac{\rho}{\phi\mu}\Bigr]
      =-\frac{(\phi\mu+\rho)(\tau_{u}+\tau_{v})}{\phi\mu}\;,
\end{equation*}
so that $c^{*}\to\kappa$ for $S\to\infty$.  In particular

\begin{equation*}
\kappa_{0}\equiv -\,{\rm sign}\,\kappa
        =1+\frac{\rho}{\phi\mu}
        =\frac{\phi\mu+\rho}{\phi\mu},
\end{equation*}
is the dimensionless Hebbian–heterosynaptic drive–offset ratio which
is normally quoted.  With the filter overlap absorbed, $I\to1$, this is
the textbook form

\begin{equation*}
c^{*}= \frac{-\,\kappa_{0}S-1}{S-1},\qquad 
\kappa_{0}=1+\frac{\rho}{\phi\mu},
\end{equation*}
i.e. up to the inessential overall sign $c^{*}=(\kappa_{+}S-1)/(S-1)$ with
$\kappa_{+}=1+\rho/\phi\mu$.  In the signed convention
$\tau_{w}\dot w_{k}=u_{k}(v_{k}+\rho)$ used in the statement the
parameter which literally multiplies $S$ in $c^{*}=(\kappa S-1)/(S-1)$ is
$\kappa=-\kappa_{0}=-1-\rho/\phi\mu$, and with the overlap kept explicit
$\kappa=-(\tau_{u}+\tau_{v})\kappa_{0}$.  Up to the conventional $+1$
coming from $c_{kk}=1$ this is often written in the positive LTD
convention as $\kappa_{+}=1+\rho/\phi\mu\approx -\rho/\phi\mu$ for
$\rho<0$, i.e. in dimensional form

\begin{equation*}
|\kappa|\propto\Bigl(\mu+\frac{\rho}{\phi}\Bigr)
           (\tau_{u}+\tau_{v}) ,
\end{equation*}
which reduces to the familiar dimensionless homeostatic ratio
$1+\rho/\phi\mu$ after the usual $I\to1$ normalisation.  Changing the
conventional sign $\rho\to-\rho$ this is the textbook positive form
$\kappa=1+\rho/\phi\mu$, $c^{*}\to\kappa$ for $S\to\infty$, the usual
$-\rho/\phi\mu$ homeostatic offset to the mean Hebbian drive $\phi\mu$.
The additive $1$ is the self–correlation $c_{kk}=1$ and is normally
absorbed in the definition of $S$. ∎

public_text.3:
In the mean field on the $w$ time scale put $x_{k}=\mu +\xi _{k}$,
$\langle\xi _{k}\rangle =0$, $\langle\xi _{k}(t)\xi _{l}(t')\rangle \propto
c_{kl}\delta(t-t')$ and

\begin{equation*}
v_{k}(t)=\phi\int_{0}^{\infty}h_{v}(s)x_{k}(t-s)ds,\qquad
u_{k}(t)=w\sum_{l}s_{kl}\int_{0}^{\infty}h_{u}(s)x_{l}(t-s)ds ,
\end{equation*}
$h_{v,u}(s)=\tau_{v,u}^{-1}e^{-s/\tau_{v,u}}$, ${\cal O}=\int_{0}^{\infty}
h_{v}h_{u}ds=(\tau_{u}+\tau_{v})^{-1}$.  On the $w$ time scale

\begin{equation*}
\langle v_{k}\rangle =\phi\mu ,\qquad 
\langle u_{k}\rangle =w\mu S_{k}, \qquad S_{k}=\sum_{l}s_{kl},
\end{equation*}
and with the white noise normalisation $\langle x_{k}x_{l}\rangle=
\mu^{2}c_{kl}$, $c_{kk}=1$,

\begin{equation*}
\langle u_{k}v_{k}\rangle=
\phi w\mu^{2}S_{k}+\phi w\mu^{2}{\cal O}\sum_{l}s_{kl}c_{kl}\; .
\end{equation*}
Hence

\begin{equation*}
0=\big\langle u_{k}\big(v_{k}+\rho\big)\big\rangle
 =\langle u_{k}v_{k}\rangle+\rho\langle u_{k}\rangle
\end{equation*}
gives, up to the irrelevant overall factor $w\mu>0$,

\begin{equation*}
\phi\mu S_{k}+\rho S_{k}
     +\phi\mu{\cal O}\sum_{l}s_{kl}c_{kl}=0 .
\end{equation*}
On the homogeneous manifold $w_{l}\equiv w$, $\mu_{l}\equiv\mu$,
$S_{k}\equiv S$ and with $c_{kl}=c$, $k\ne l$, $c_{kk}=1$,
$s_{kk}=1$,

\begin{equation*}
\sum_{l}s_{kl}c_{kl}=1+c\,(S-1),
\end{equation*}
so that

\begin{equation*}
S\Big[\phi\mu+\rho\Big]+\phi\mu{\cal O}\Big[\,1+c\,(S-1)\Big]=0,
\end{equation*}
i.e.

\begin{equation*}
1+c\,(S-1)=-\frac{S}{{\cal O}}\,
          \frac{\phi\mu+\rho}{\phi\mu}\; .
\end{equation*}
With the conventional normalisation ${\cal O}\to1$, i.e. the overlap
$(\tau_{u}+\tau_{v})^{-1}$ absorbed in the definition of $\phi$,

\begin{equation*}
1+c\,(S-1)=-S\,\frac{\phi\mu+\rho}{\phi\mu},
\end{equation*}
and

\begin{equation*}
c^{*}= \frac{-\,S\,\dfrac{\phi\mu+\rho}{\phi\mu}-1}{S-1}
     =\frac{\kappa_{s}S-1}{S-1},\qquad 
\kappa_{s}=-\,\frac{\phi\mu+\rho}{\phi\mu}
        =-\Bigl[1+\frac{\rho}{\phi\mu}\Bigr] .
\end{equation*}
The $S$–independent, dimensionless Hebbian–heterosynaptic ratio is
therefore

\begin{equation*}
\kappa_{0}\equiv\frac{\phi\mu+\rho}{\phi\mu}
        =1+\frac{\rho}{\phi\mu},
\end{equation*}
which is the quantity normally quoted as the local homeostatic
threshold.  In particular $c^{*}\to\kappa_{0}$ for $S\to\infty$ and
the isolated synapse condition is $\phi\mu(1+c)+\rho=0$.  For the
usual LTD offset $\rho<0$ this is the positive number
$\kappa_{+}=1+\rho/\phi\mu=1-|\rho|/\phi\mu\approx-\rho/\phi\mu$.
With the sign convention $\tau_{w}\dot w_{k}=u_{k}(v_{k}+\rho)$ used in
the statement the signed parameter which is literally written as
$c^{*}=(\kappa S-1)/(S-1)$ is $\kappa_{s}=-\kappa_{0}=-1-\rho/\phi\mu$,
i.e. up to the inessential overall sign $\kappa=\kappa_{0}$.  Keeping
the filter overlap explicit ${\cal O}=(\tau_{u}+\tau_{v})^{-1}$ the
$S$ independent combination is

\begin{equation*}
\kappa_{{\cal I}}=-\frac{1}{{\cal O}}\Bigl[1+\frac{\rho}{\phi\mu}\Bigr]
       =-(\tau_{u}+\tau_{v})\Bigl[1+\frac{\rho}{\phi\mu}\Bigr]
       =-\frac{(\phi\mu+\rho)(\tau_{u}+\tau_{v})}{\phi\mu},
\end{equation*}
i.e. in dimensional form $\kappa\propto(\mu+\rho/\phi)(\tau_{u}+\tau_{v})$,
which after the usual absorption ${\cal O}\to1$ reduces to the familiar
dimensionless control parameter $\kappa_{0}=1+\rho/\phi\mu$, often quoted
in the positive LTD convention as $\kappa_{+}\approx-\rho/\phi\mu$.  The
change of sign $\rho\to-\rho$ removes the minus sign and gives the
text-book form $c^{*}=(\kappa S-1)/(S-1)$ with
$\kappa=1+\rho/\phi\mu=(\phi\mu+\rho)/\phi\mu$, whence
$\lim_{S\to\infty}c^{*}=\kappa$ and $c^{*}\simeq-\rho/\phi\mu$ for
$|\rho|\gg\phi\mu$.  This is the $1+\rho/\phi\mu$ drive–offset ratio
that sets the asymptotic critical correlation. ∎

