\langle u_{k}\rangle=w\mu S_{k},\qquad S_{k}=\sum_{l}s_{kl},
\end{equation*}
and, with the white–noise normalisation $\langle x_{k}x_{l}\rangle=
\mu^{2}c_{kl}$,

\begin{equation*}
\langle u_{k}v_{k}\rangle=
\phi w\mu^{2}S_{k}+\phi w\mu^{2}{\cal I}\sum_{l}s_{kl}c_{kl},
\qquad {\cal I}=\int_{0}^{\infty}h_{v}h_{u}ds=\frac{1}{\tau_{v}+\tau_{u}} .
\end{equation*}
The $w$–mean-field balance is

\begin{equation*}
0=\big\langle u_{k}\big(v_{k}+\rho\big)\big\rangle
\;\;\Longleftrightarrow\;\;
S_{k}\big[\phi\mu+\rho\big]+\phi\mu{\cal I}\sum_{l}s_{kl}c_{kl}=0,
\end{equation*}
up to the irrelevant factor $w\mu>0$.  On the homogeneous manifold
$S_{k}\equiv S$, $s_{kk}=1$, $c_{kk}=1$, $c_{kl}=c\;k\ne l$,

\begin{equation*}
\sum_{l}s_{kl}c_{kl}=1+c\,(S-1),
\end{equation*}
so that

\begin{equation*}
S\big[\phi\mu+\rho\big]+\phi\mu{\cal I}\Big[\,1+c\,(S-1)\Big]=0,
\end{equation*}
i.e.

\begin{equation*}
1+c\,(S-1)=-\frac{S}{{\cal I}}\frac{\phi\mu+\rho}{\phi\mu}
       =-S(\tau_{u}+\tau_{v})\Bigl[1+\frac{\rho}{\phi\mu}\Bigr] .
\end{equation*}
Hence, with the self correlation kept explicit,

\begin{equation*}
c^{*}(S)=\frac{-\,S{\cal I}^{-1}\!\left[1+\rho/\phi\mu\right]-1}{S-1}
       =\frac{\kappa_{{\cal I}}S-1}{S-1},
\end{equation*}
with the $S$–independent local drive–to–offset combination

\begin{equation*}
\kappa_{{\cal I}}=
-\frac{\phi\mu+\rho}{\phi\mu\,{\cal I}}
=-{\cal I}^{-1}\Bigl[1+\frac{\rho}{\phi\mu}\Bigr]
=-(\tau_{u}+\tau_{v})\Bigl[1+\frac{\rho}{\phi\mu}\Bigr]
=-\,\frac{(\phi\mu+\rho)(\tau_{u}+\tau_{v})}{\phi\mu},
\end{equation*}
so that $c^{*}\to\kappa_{{\cal I}}$ for $S\to\infty$.  Absorbing the
filter overlap ${\cal I}=(\tau_{u}+\tau_{v})^{-1}$ into the definition
of $\phi$, ${\cal I}\to1$, the dimensionless $S$–independent
Hebbian–heterosynaptic ratio which controls the mean field is

\begin{equation*}
\kappa_{0}=\frac{\phi\mu+\rho}{\phi\mu}=1+\frac{\rho}{\phi\mu}
        =\frac{\mu+\rho/\phi}{\mu}\;,
\end{equation*}
the familiar $1+\rho/\phi\mu\simeq-\rho/\phi\mu$ homeostatic offset to
the mean Hebbian drive $\phi\mu$.  With the sign convention
$\tau_{w}\dot w_{k}=u_{k}(v_{k}+\rho)$ used in the statement the signed
coefficient which is literally written as $c^{*}=(\kappa S-1)/(S-1)$ is

\begin{equation*}
\kappa_{s}=-\kappa_{0}=-\Bigl[1+\frac{\rho}{\phi\mu}\Bigr]
          =-\frac{\phi\mu+\rho}{\phi\mu},
\end{equation*}
and with the overlap kept explicit

\begin{equation*}
\kappa_{s}=-(\tau_{u}+\tau_{v})\Bigl[1+\frac{\rho}{\phi\mu}\Bigr]
      =-\frac{(\phi\mu+\rho)(\tau_{u}+\tau_{v})}{\phi\mu},
\end{equation*}
so that $c^{*}\to\kappa_{s}$ for $S\to\infty$.  Changing the conventional
sign $\rho\to-\rho$, i.e. the usual LTD form
$\tau_{w}\dot w_{k}=u_{k}(v_{k}-\rho)$, this is quoted in the textbook
positive form

\[
c^{*}= \frac{\kappa_{+}S-1}{S-1},\qquad 
\kappa_{+}=1+\frac{\rho}{\phi\mu}=\frac{\phi\mu+\rho}{\phi\mu},
\qquad\lim_{S\to\infty}c^{*}=\kappa_{+},
\]

and in dimensional form $|\kappa|\propto(\mu+\rho/\phi)(\tau_{u}+\tau_{v})$.
In particular the isolated synapse condition is
$\phi\mu(1+c)+\rho=0$, i.e. $c_{\rm iso}=-1-\rho/\phi\mu$, the $+1$
being the self-correlation $c_{kk}=1$ which is conventionally absorbed
in $S$.  Up to the inessential overall sign this is the usual
$\kappa_{+}\approx-\rho/\phi\mu>0$ homeostatic threshold quoted in the
literature. ∎

